import heapq

def match(orders):
    trades = []
    buy_heap = []   # entries: (-price, seq, id)
    sell_heap = []  # entries: (price, seq, id)
    orders_info = {}  # id -> {'side','qty','active'}
    seq_counter = 0

    def clean_top(book):
        while book:
            top = book[0]
            oid = top[-1]
            info = orders_info.get(oid)
            if info is None or (not info['active']) or info['qty'] <= 0:
                heapq.heappop(book)
                continue
            break

    def do_match(incoming_side, incoming_id, incoming_price, incoming_qty, is_market):
        book = sell_heap if incoming_side == 'buy' else buy_heap
        while incoming_qty > 0:
            clean_top(book)
            if not book:
                break
            top = book[0]
            if incoming_side == 'buy':
                price = top[0]
            else:
                price = -top[0]
            oid = top[-1]
            info = orders_info[oid]

            if not is_market:
                if incoming_side == 'buy' and price > incoming_price:
                    break
                if incoming_side == 'sell' and price < incoming_price:
                    break

            heapq.heappop(book)
            trade_qty = min(incoming_qty, info['qty'])
            info['qty'] -= trade_qty
            incoming_qty -= trade_qty

            if incoming_side == 'buy':
                trades.append([incoming_id, oid, price, trade_qty])
            else:
                trades.append([oid, incoming_id, price, trade_qty])

            if info['qty'] > 0:
                heapq.heappush(book, top)
            else:
                info['active'] = False
        return incoming_qty

    for order in orders:
        typ = order[0]

        if typ == 'cancel':
            oid = order[1]
            info = orders_info.get(oid)
            if info is not None and info['active']:
                info['active'] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
            remaining = do_match(side, oid, price, qty, False)
            if remaining > 0:
                orders_info[oid] = {'side': side, 'qty': remaining, 'active': True}
                if side == 'buy':
                    heapq.heappush(buy_heap, (-price, seq_counter, oid))
                else:
                    heapq.heappush(sell_heap, (price, seq_counter, oid))
                seq_counter += 1
            else:
                # fully filled immediately, still track for consistency
                orders_info[oid] = {'side': side, 'qty': 0, 'active': False}
                seq_counter += 1

        elif typ == 'ioc':
            _, oid, side, price, qty = order
            do_match(side, oid, price, qty, False)
            seq_counter += 1

        elif typ == 'market':
            _, oid, side, qty = order
            do_match(side, oid, None, qty, True)
            seq_counter += 1

    return trades

